//! Experimental load-time expansion of Tract's Q4 constants.
use tract_onnx::{
    prelude::*,
    tract_core::internal::tract_linalg::block_quant::BlockQuantStorage,
    tract_core::{internal::ensure, ops::konst::Const},
};

/// Expand the values already represented by Q4 storage. Do not re-quantize weights.
/// Keep the zero-point correction nodes generated by the ONNX importer.
pub fn expand_weights(model: &mut TypedModel) -> TractResult<(usize, usize)> {
    let mut count = 0;
    let mut packed_bytes = 0;
    let mut expanded_bytes = 0;
    for node in &mut model.nodes {
        let Some(konst) = node.op_as::<Const>() else {
            continue;
        };
        let Some(storage) = konst.val().storage_as::<BlockQuantStorage>() else {
            continue;
        };
        let tensor = storage
            .format()
            .dequant_f32(storage.value())?
            .into_shape(konst.val().shape())?
            .into_arc_tensor();
        count += 1;
        packed_bytes += storage.value().len();
        expanded_bytes += tensor.len() * std::mem::size_of::<f32>();
        let op = Const::new(tensor)?;
        node.outputs[0].fact = op.output_facts(&[])?.remove(0);
        node.op = Box::new(op);
    }
    ensure!(
        count == 37,
        "expected 37 packed weight constants, found {count}"
    );
    Ok((packed_bytes, expanded_bytes))
}
